/**
 * Get the number of attendees interested in an event
 */
export const getEventInterestCount = async (eventId: string): Promise<number> => {
  try {
    const { count, error } = await supabase
      .from("event_attendees")
      .select("*", { count: "exact", head: true })
      .eq("event_id", eventId);
    
    if (error) throw error;
    
    return count || 0;
  } catch (error) {
    console.error("Error getting event interest count:", error);
    return 0;
  }
};

/**
 * Check if a user is interested in an event
 */
export const isUserInterestedInEvent = async (eventId: string, userId: string): Promise<boolean> => {
  try {
    const { data, error } = await supabase
      .from("event_attendees")
      .select("*")
      .eq("event_id", eventId)
      .eq("user_id", userId)
      .maybeSingle();
    
    if (error) throw error;
    
    return !!data;
  } catch (error) {
    console.error("Error checking if user is interested in event:", error);
    return false;
  }
};

/**
 * Get attendees for an event
 */
export const getEventAttendees = async (eventId: string, includeProfiles = false): Promise<any[]> => {
  try {
    let query = supabase
      .from("event_attendees")
      .select(includeProfiles ? "*, profile:profiles(*)" : "*")
      .eq("event_id", eventId);
    
    const { data, error } = await query;
    
    if (error) throw error;
    
    return data || [];
  } catch (error) {
    console.error("Error getting event attendees:", error);
    throw error;
  }
};

/**
 * Check in a user to an event
 */
export const checkInUserToEvent = async (eventId: string, userId: string): Promise<boolean> => {
  try {
    // First, check if the user has already registered interest
    const { data: existingData, error: existingError } = await supabase
      .from("event_attendees")
      .select("*")
      .eq("event_id", eventId)
      .eq("user_id", userId)
      .maybeSingle();
    
    if (existingError) throw existingError;
    
    if (existingData) {
      // User already registered interest, update check-in time
      const { error } = await supabase
        .from("event_attendees")
        .update({ check_in_time: new Date().toISOString() })
        .eq("event_id", eventId)
        .eq("user_id", userId);
      
      if (error) throw error;
    } else {
      // User has not registered interest, create new record
      const { error } = await supabase
        .from("event_attendees")
        .insert({
          event_id: eventId,
          user_id: userId,
          check_in_time: new Date().toISOString()
        });
      
      if (error) throw error;
    }
    
    // Increment the events_attended count in the user's profile
    await incrementEventsAttendedCount(userId);
    
    return true;
  } catch (error) {
    console.error("Error checking in user to event:", error);
    return false;
  }
};

/**
 * Increment the events_attended count in a user's profile
 */
export const incrementEventsAttendedCount = async (userId: string): Promise<void> => {
  try {
    // First, get the current count
    const { data: profile, error: profileError } = await supabase
      .from("profiles")
      .select("events_attended")
      .eq("id", userId)
      .maybeSingle();
    
    if (profileError) throw profileError;
    
    // Calculate new count
    const currentCount = profile?.events_attended || 0;
    const newCount = currentCount + 1;
    
    // Update the profile
    const { error: updateError } = await supabase
      .from("profiles")
      .update({ events_attended: newCount })
      .eq("id", userId);
    
    if (updateError) throw updateError;
  } catch (error) {
    console.error("Error incrementing events attended count:", error);
  }
};
